<?php
namespace Tests\Feature;
use App\Models\Order;use App\Models\Product;use App\Models\ProductVariant;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Tests\TestCase;
class Pack005CommerceTest extends TestCase {use RefreshDatabase;private function variant():ProductVariant{$p=Product::create(['name'=>'Cart Product','slug'=>'cart-'.Str::random(6),'product_type'=>'variable','status'=>'active']);return ProductVariant::create(['product_id'=>$p->id,'name'=>'M','sku'=>'SKU-'.Str::random(8),'cost_price'=>50,'price'=>100,'track_inventory'=>false,'is_active'=>true]);}public function test_guest_can_add_to_cart():void{$this->seed();$v=$this->variant();$this->post(route('cart.store',$v),['quantity'=>2])->assertRedirect(route('cart.index'));$this->get(route('cart.index'))->assertOk()->assertSee('Cart Product');}public function test_guest_can_create_pending_order():void{$this->seed();$v=$this->variant();$this->post(route('cart.store',$v),['quantity'=>1]);$this->post(route('checkout.store'),['customer_name'=>'Test Buyer','phone'=>'01700000000','email'=>'buyer@example.com','country_code'=>'BD','division'=>'Dhaka','city'=>'Dhaka','address'=>'Test address','shipping_method'=>'standard'])->assertRedirect();$this->assertDatabaseHas('orders',['customer_name'=>'Test Buyer','status'=>'pending_payment','payment_status'=>'unpaid']);$this->assertDatabaseCount('order_items',1);}public function test_compare_accepts_four_products_max():void{$this->seed();for($i=0;$i<5;$i++){$v=$this->variant();$this->post(route('compare.toggle',$v->product));}$this->assertCount(4,session('amer_compare'));}}
